  // ── Tool uninstall (manifest audience removal + force_redownload) ──
  // True uninstall is a TWO-STEP operation:
  //   1. Edit tools-manifest-v3.json — remove user's email from the tool's
  //      audienceEmails. Without this, the user's next sync auto-installs
  //      the tool back (manifest still lists them in audience).
  //   2. Push a force_redownload_tool override targeted at this user. That
  //      action calls eli.tools.uninstall on their machine → removes from
  //      IDB → tile vanishes from their dashboard.
  // Result: tool gone, won't auto-reinstall. To re-grant access later,
  // add the email back to the manifest audience and run Force re-install.
  function _showToolUninstaller(userId, toolId) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email for manifest audience)", "err");
      return;
    }
    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_warn">⚠️ <b>Permanent uninstall.</b> ' +
        'Two steps: (1) remove user from the manifest audience so it won\'t re-install, ' +
        '(2) push force_redownload to clear from their IDB. ' +
        'To restore access later you\'ll have to manually add the user back to the manifest audience.</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_uninst_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';
    showEliDialog({
      variant: "warning",
      icon: "🗑",
      title: "Uninstall tool from user",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Uninstall",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var reason = (document.getElementById("_af_uninst_reason").value || "").trim();
            _toast("⏳ Editing manifest…", "info");
            // Step 1: edit tools-manifest-v3.json to exclude this user.
            // Two paths depending on the tool's existing audience:
            //   • Has audienceEmails (per-email inclusion list) — remove
            //     the user's email from it.
            //   • Has audience: ["all"] OR no inclusion list — add the
            //     user's email to audienceEmailExcludes (negative filter,
            //     2026-05-23 kernel addition). Preserves "broadcast to
            //     everyone else" semantics.
            // Result either way: this user no longer matches the audience
            // on next sync → tool won't re-install after the override-
            // driven uninstall.
            _ghGet("tools-manifest-v3.json").then(function (r) {
              if (!r) throw new Error("tools-manifest-v3.json not found on CDN");
              var manifest;
              try { manifest = JSON.parse(_b64ToStr(r.content)); }
              catch (e) { throw new Error("manifest parse failed: " + e.message); }
              var sha = r.sha;
              var tools = manifest && manifest.tools;
              if (!Array.isArray(tools)) throw new Error("manifest has no tools array");
              var entry = tools.find(function (t) { return t && t.id === toolId; });
              if (!entry) throw new Error("tool " + toolId + " not in manifest");
              var emailLc = id.email.toLowerCase();
              var hasInclusion = Array.isArray(entry.audienceEmails) && entry.audienceEmails.length > 0;
              if (hasInclusion) {
                // Per-email audience — remove user's email from inclusion list.
                var before = entry.audienceEmails.length;
                entry.audienceEmails = entry.audienceEmails.filter(function (em) {
                  return String(em || "").toLowerCase() !== emailLc;
                });
                if (entry.audienceEmails.length === before) {
                  eli.log.event("tool", "admin_fleet_uninstall_not_in_audience", { toolId: toolId, email: id.email });
                }
              } else {
                // Broadcast audience (or no list) — add to exclude list.
                if (!Array.isArray(entry.audienceEmailExcludes)) entry.audienceEmailExcludes = [];
                var alreadyExcluded = entry.audienceEmailExcludes.some(function (em) {
                  return String(em || "").toLowerCase() === emailLc;
                });
                if (!alreadyExcluded) entry.audienceEmailExcludes.push(id.email);
              }
              manifest.lastUpdated = new Date().toISOString();
              var json = JSON.stringify(manifest, null, 2);
              var msg = "admin_fleet: uninstall " + toolId + " from " + id.email + " @ " +
                new Date().toISOString().replace("T", " ").replace(/\..*/, "");
              return _ghPut("tools-manifest-v3.json", json, msg, sha);
            }).then(function () {
              _toast("⏳ Pushing uninstall override…", "info");
              // Step 2: push force_redownload_tool override
              var overrideId = "fleet-uninstall-" + toolId + "-" + userId + "-" + Date.now();
              var entry = {
                id: overrideId,
                audienceEmails: [id.email],
                actions: [{ type: "force_redownload_tool", toolId: toolId }],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              };
              if (reason) entry.note = reason;
              return _pushOverride(entry);
            }).then(function () {
              _toast("✅ Uninstalled " + toolId + " from " + _displayName(userId), "ok");
              // Refresh local manifest cache so the excluded-tools section
              // shows the new exclusion on next render.
              return _fetchToolsManifest().then(function () { _renderDashboard(); });
            }).catch(function (err) {
              _toast("Uninstall failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

