              var manifest;
              try { manifest = JSON.parse(_b64ToStr(r.content)); }
              catch (e) { throw new Error("manifest parse failed: " + e.message); }
              var sha = r.sha;
              var entry = (manifest.tools || []).find(function (t) { return t && t.id === toolId; });
              if (!entry) throw new Error("tool " + toolId + " not in manifest");
              if (!Array.isArray(entry.audienceEmailExcludes)) entry.audienceEmailExcludes = [];
              var emailLc = id.email.toLowerCase();
              var before = entry.audienceEmailExcludes.length;
              entry.audienceEmailExcludes = entry.audienceEmailExcludes.filter(function (em) {
                return String(em || "").toLowerCase() !== emailLc;
              });
              if (entry.audienceEmailExcludes.length === before) {
                eli.log.event("tool", "admin_fleet_regrant_not_excluded", { toolId: toolId, email: id.email });
              }
