              manifest.lastUpdated = new Date().toISOString();
              var json = JSON.stringify(manifest, null, 2);
              var msg = "admin_fleet: re-grant " + toolId + " to " + id.email + " @ " +
                new Date().toISOString().replace("T", " ").replace(/\..*/, "");
