              if (!triggerInstall) return;
              // Step 2 (optional): push force_redownload to trigger install
              _toast("⏳ Pushing install override…", "info");
              var overrideId = "fleet-regrant-" + toolId + "-" + userId + "-" + Date.now();
              var entry = {
