  // ── Dashboard rendering ──────────────────────────────────────────
  function _renderDashboard() {
    var out = window.eli.ui.claimOutput();
    out.classList.add("eli-view-enter");

    var unresolved = _unresolvedUsers();
    var resolved = _allUsers().filter(function (uid) { return _lookup[uid]; });
    var overridesByEmail = {};
    (_adminOverrides && _adminOverrides.overrides || []).forEach(function (o) {
      (o.audienceEmails || []).forEach(function (em) {
        if (!overridesByEmail[em]) overridesByEmail[em] = [];
        overridesByEmail[em].push(o);
      });
    });

    function _renderUserCard(userId) {
      var id = _identityFor(userId);
      var fleet = _telemetryByUserId[userId];
      // Legacy fallback — for "AN-legacy" style synthetic IDs that have a
      // telemetry file but no fleet block yet, pull what we can from the
      // raw digest (days array, etc.) so the card isn't entirely empty.
      var legacyKey = _legacyUserKey(userId);
      var legacyDigest = legacyKey ? _telemetryRowsByUserKey[legacyKey] : null;
      var isLegacy = !!legacyDigest && !fleet;
      var nm = id ? _displayName(userId) : userId;
      var role = id && id.role ? id.role : "—";
      var status = id && id.status ? id.status : "—";
      var email = id && id.email ? id.email : "—";
      var lastSeen = fleet && fleet.lastSeenAt ? _ago(fleet.lastSeenAt)
        : (legacyDigest && legacyDigest.days && legacyDigest.days.length
            ? "legacy: last day " + legacyDigest.days[legacyDigest.days.length - 1].date
            : "never");
      var installedAt = fleet && fleet.installedAt ? new Date(fleet.installedAt).toLocaleDateString() : "—";
      var aiModel = fleet && fleet.settings && fleet.settings.ai_model || "—";
      var kernelV = fleet && fleet.kernelVersion || "—";
      var toolCount = fleet && fleet.tools ? fleet.tools.length : 0;
      var activeOverrides = email !== "—" ? (overridesByEmail[email] || []) : [];

      var statusBadge = '<span class="_eli3_af_badge _eli3_af_badge_' + _esc(status) + '">' + _esc(status) + '</span>';
      var roleBadge = role !== "—" ? '<span class="_eli3_af_badge _eli3_af_badge_role">' + _esc(role) + '</span>' : '';
      var legacyBadge = isLegacy
        ? '<span class="_eli3_af_badge _eli3_af_badge_legacy" title="Telemetry exists but pre-dates fleet payload. Next push from this user will populate full fleet data.">⏳ legacy</span>'
        : '';

      var actionsHtml = '';
      if (id) {
        actionsHtml =
          '<button class="_eli3_af_btn _eli3_af_btn_primary" data-act="push-setting" data-uid="' + _esc(userId) + '">⚙️ Push setting</button>' +
          '<button class="_eli3_af_btn" data-act="edit-identity" data-uid="' + _esc(userId) + '">✏️ Edit identity</button>';
      } else {
        actionsHtml =
          '<button class="_eli3_af_btn _eli3_af_btn_primary" data-act="add-identity" data-uid="' + _esc(userId) + '">🆕 Identify this user</button>';
      }

      var toolsList = "";
      if (fleet && fleet.tools && fleet.tools.length) {
        toolsList = '<div class="_eli3_af_tools">' +
          '<div class="_eli3_af_tools_header">Tools (' + fleet.tools.length + ')</div>' +
          '<div class="_eli3_af_tools_list">' +
            fleet.tools.map(function (t) {
              var disabledMark = t.disabled ? ' <span class="_eli3_af_tools_disabled">(disabled)</span>' : '';
              return '<div class="_eli3_af_tools_row">' +
                '<span class="_eli3_af_tools_id">' + _esc(t.id) + '</span>' +
                disabledMark +
                (id ? (
                  '<div class="_eli3_af_tools_actions">' +
                    (t.disabled
                      ? '<button class="_eli3_af_btn_mini" data-act="tool-enable" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">▶ Enable</button>'
                      : '<button class="_eli3_af_btn_mini" data-act="tool-disable" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">⏸ Disable</button>') +
                    '<button class="_eli3_af_btn_mini" data-act="tool-redownload" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">↺ Re-DL</button>' +
                    '<button class="_eli3_af_btn_mini _eli3_af_btn_danger" data-act="tool-uninstall" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '" title="Remove from manifest audience + delete from IDB. Permanent until you re-add via manifest.">🗑 Uninstall</button>' +
                  '</div>'
                ) : '') +
              '</div>';
            }).join('') +
          '</div>' +
        '</div>';
      }

      var settingsList = "";
      if (fleet && fleet.settings) {
        var sKeys = Object.keys(fleet.settings).filter(function (k) {
          var v = fleet.settings[k];
          return v !== null && v !== undefined && v !== "";
        });
        if (sKeys.length) {
          settingsList = '<div class="_eli3_af_settings">' +
            '<div class="_eli3_af_settings_header">Settings (' + sKeys.length + ')</div>' +
            '<div class="_eli3_af_settings_list">' +
              sKeys.map(function (k) {
                return '<div class="_eli3_af_settings_row">' +
                  '<span class="_eli3_af_settings_key">' + _esc(k) + ':</span> ' +
                  '<span class="_eli3_af_settings_val">' + _esc(String(fleet.settings[k])) + '</span>' +
                '</div>';
              }).join('') +
            '</div>' +
          '</div>';
        }
      }

      var overridesList = "";
      if (activeOverrides.length) {
        overridesList = '<div class="_eli3_af_overrides">' +
          '<div class="_eli3_af_overrides_header">Active admin pushes (' + activeOverrides.length + ')</div>' +
          activeOverrides.map(function (o) {
            var actionSummary = (o.actions || []).map(function (a) {
              if (a.type === "set_setting") return a.key + " = " + JSON.stringify(a.value) + " (" + (a.force === true ? "force" : a.force === "reset" ? "reset" : "soft") + ")";
              if (a.type === "disable_tool") return "disable " + a.toolId;
              if (a.type === "enable_tool") return "enable " + a.toolId;
              if (a.type === "force_redownload_tool") return "re-download " + a.toolId;
              return a.type;
            }).join("; ");
            return '<div class="_eli3_af_overrides_row">' +
              '<span>' + _esc(actionSummary) + '</span>' +
              ' <button class="_eli3_af_btn_mini _eli3_af_btn_danger" data-act="remove-override" data-oid="' + _esc(o.id) + '">🗑 Remove</button>' +
            '</div>';
          }).join('') +
        '</div>';
      }

      // Prominent installed-tools line — shows top N tool IDs at a glance,
      // with "+N more" if list is longer. Full per-tool action buttons
      // remain below in the toolsList section.
      var installedToolsLine = "";
      if (fleet && fleet.tools && fleet.tools.length) {
        var visibleIds = fleet.tools.slice(0, 8).map(function (t) {
          return t.disabled ? '<span style="opacity:0.5;text-decoration:line-through">' + _esc(t.id) + '</span>' : _esc(t.id);
        });
        var more = fleet.tools.length > 8 ? ' <span style="opacity:0.6;">+' + (fleet.tools.length - 8) + ' more</span>' : '';
        installedToolsLine =
          '<div class="_eli3_af_installed_line" title="Tools currently installed on this user\'s machine">' +
            '<span class="_eli3_af_installed_label">Installed (' + fleet.tools.length + '):</span> ' +
            visibleIds.join(", ") + more +
          '</div>';
      } else if (legacyDigest) {
        installedToolsLine =
          '<div class="_eli3_af_installed_line _eli3_af_installed_line_legacy" title="Telemetry pre-dates fleet payload; tool list will populate after their next push">' +
            '<span class="_eli3_af_installed_label">Installed:</span> ' +
            '<span style="opacity:0.6">(unknown — needs fleet-block push)</span>' +
          '</div>';
      }

      // Excluded tools — tools where this user is in audienceEmailExcludes
      // on the manifest. Each gets a Re-grant button.
      var excludedList = "";
      var excluded = _excludedToolsForUser(userId);
      if (excluded.length) {
        excludedList = '<div class="_eli3_af_excluded">' +
          '<div class="_eli3_af_excluded_header">🚫 Excluded by admin (' + excluded.length + ')</div>' +
          excluded.map(function (tid) {
            return '<div class="_eli3_af_excluded_row">' +
              '<span class="_eli3_af_excluded_id">' + _esc(tid) + '</span>' +
              '<button class="_eli3_af_btn_mini" data-act="tool-regrant" data-uid="' + _esc(userId) + '" data-tool="' + _esc(tid) + '">↩️ Re-grant</button>' +
            '</div>';
          }).join('') +
        '</div>';
      }

      return '<div class="_eli3_af_card" data-uid="' + _esc(userId) + '">' +
        '<div class="_eli3_af_card_header">' +
          '<div class="_eli3_af_card_name">' + _esc(nm) + '</div>' +
          '<div class="_eli3_af_card_badges">' + roleBadge + statusBadge + legacyBadge + '</div>' +
        '</div>' +
        '<div class="_eli3_af_card_meta">' +
          '<span title="User ID">' + _esc(userId) + '</span>' +
          ' · <span title="Email">' + _esc(email) + '</span>' +
          ' · <span title="Last telemetry upload">last seen ' + _esc(lastSeen) + '</span>' +
          ' · <span title="Install date">installed ' + _esc(installedAt) + '</span>' +
          ' · <span title="Kernel version">' + _esc(kernelV) + '</span>' +
          ' · <span title="Tools count">' + toolCount + ' tools</span>' +
          ' · <span title="Current AI model">model: ' + _esc(aiModel) + '</span>' +
        '</div>' +
        installedToolsLine +
        '<div class="_eli3_af_card_actions">' + actionsHtml + '</div>' +
        settingsList +
        toolsList +
        excludedList +
        overridesList +
      '</div>';
    }

    var headerHtml =
      '<div class="_eli3_af_header">' +
        '<div class="_eli3_af_header_title">' +
          '<span class="_eli3_af_header_icon">👥</span>' +
          '<span>ELI Fleet</span>' +
        '</div>' +
        '<div class="_eli3_af_header_meta">' +
          _allUsers().length + ' users · ' +
          unresolved.length + ' unresolved · ' +
          (_adminOverrides && _adminOverrides.overrides ? _adminOverrides.overrides.length : 0) + ' active pushes' +
        '</div>' +
        '<div class="_eli3_af_header_actions">' +
          '<button class="_eli3_af_btn" id="_af_refresh">🔄 Refresh</button>' +
          '<button class="_eli3_af_btn" id="_af_close">✕ Close</button>' +
        '</div>' +
      '</div>';

    var unresolvedHtml = "";
    if (unresolved.length) {
      unresolvedHtml = '<div class="_eli3_af_section">' +
        '<div class="_eli3_af_section_header">🆕 Unresolved users — click "Identify" to add them to your lookup</div>' +
        unresolved.map(_renderUserCard).join("") +
      '</div>';
    }

    var resolvedHtml = '<div class="_eli3_af_section">' +
      '<div class="_eli3_af_section_header">Resolved users (' + resolved.length + ')</div>' +
      (resolved.length ? resolved.map(_renderUserCard).join("") :
        '<div class="_eli3_af_empty">No users in the lookup table yet. Identify one above to get started.</div>') +
    '</div>';

    out.innerHTML =
      '<div class="_eli3_af_root">' +
        headerHtml +
        unresolvedHtml +
        resolvedHtml +
      '</div>';

    // Wire actions
    document.getElementById("_af_refresh").onclick = function () { _launch(true); };
    document.getElementById("_af_close").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    // 2026-05-23 bug fix: use .onclick assignment (replaces) instead of
    // addEventListener (stacks). _renderDashboard() runs after every save /
    // push / refresh; with addEventListener each re-render added a NEW
    // handler, so a single click opened N stacked dialogs (one per render
    // since boot). User saw "click Cancel 2-3 times to dismiss" + backdrop
    // dimming visibly getting lighter as each overlay peeled away.
    out.onclick = function (ev) {
      var t = ev.target;
      while (t && t !== out) {
        var act = t.getAttribute && t.getAttribute("data-act");
        if (act) {
          var uid = t.getAttribute("data-uid");
          if (act === "add-identity") return _showIdentityEditor(uid, true);
          if (act === "edit-identity") return _showIdentityEditor(uid, false);
          if (act === "push-setting") return _showSettingPusher(uid);
          if (act === "tool-disable") return _showToolPusher(uid, t.getAttribute("data-tool"), "disable_tool");
          if (act === "tool-enable") return _showToolPusher(uid, t.getAttribute("data-tool"), "enable_tool");
          if (act === "tool-redownload") return _showToolPusher(uid, t.getAttribute("data-tool"), "force_redownload_tool");
          if (act === "tool-uninstall") return _showToolUninstaller(uid, t.getAttribute("data-tool"));
          if (act === "tool-regrant") return _showToolRegrant(uid, t.getAttribute("data-tool"));
          if (act === "remove-override") {
            var oid = t.getAttribute("data-oid");
            if (!oid) return;
            _toast("⏳ Removing override…", "info");
            _removeOverride(oid).then(function (ok) {
              if (ok) _toast("✅ Override removed", "ok");
              _renderDashboard();
            }).catch(function (err) { _toast("Remove failed: " + err.message, "err"); });
            return;
          }
        }
        t = t.parentNode;
      }
    };
  }

  function _launch(force) {
    _toast("⏳ Loading fleet data…", "info");
    return _bootstrap().then(function () {
      _renderDashboard();
      eli.log.event("tool", "admin_fleet_loaded", {
        users: _allUsers().length,
        unresolved: _unresolvedUsers().length,
        overrides: (_adminOverrides && _adminOverrides.overrides || []).length,
      });
    }).catch(function (err) {
      _toast("Fleet load failed: " + (err.message || "unknown"), "err");
      eli.log.event("tool", "admin_fleet_load_failed", { msg: err && err.message });
      // Render a fallback message
      var out = window.eli.ui.claimOutput();
      out.innerHTML =
        '<div class="_eli3_af_root">' +
          '<div class="_eli3_af_error">' +
            '<h2>👥 ELI Fleet — Setup needed</h2>' +
            '<p>' + _esc(err.message || "Unknown error") + '</p>' +
            '<p>Make sure both <code>eli_user_github_pat</code> and <code>eli_admin_password</code> are set ' +
              '(usually via importing a credentials bundle in Admin Library Publisher).</p>' +
            '<button class="_eli3_af_btn" id="_af_retry">🔄 Retry</button>' +
          '</div>' +
        '</div>';
      document.getElementById("_af_retry").onclick = function () { _launch(); };
    });
  }

  // ── Tile registration ────────────────────────────────────────────
  if (eli.register) {
    eli.register({
      tile: {
        app_admin_fleet: eli.events.guard ? eli.events.guard(function () { _launch(); }, "admin_fleet.tile") : function () { _launch(); },
      },
    });
  }

  eli.log.event("tool", "admin_fleet_initialized", {});
}

jsonTools.css:
/* admin_fleet — fleet dashboard styling
   Light palette in both themes (per CLAUDE.md tools+dialogs rule). */

._eli3_af_root {
  font: 13px/1.4 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 16px;
  min-height: 100vh;
  box-sizing: border-box;
}

._eli3_af_header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  border-radius: 0;
  margin-bottom: 14px;
}
._eli3_af_header_title {
  font-family: 'Georgia', serif;
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}
._eli3_af_header_icon { font-size: 20px; }
._eli3_af_header_meta {
  font-size: 11px;
  color: #cbd5e1;
  letter-spacing: 0.5px;
  flex: 1;
}
._eli3_af_header_actions {
  display: flex;
  gap: 6px;
}
._eli3_af_header_actions ._eli3_af_btn {
  background: rgba(255,255,255,0.15);
  border-color: rgba(255,255,255,0.3);
  color: #fff;
}
._eli3_af_header_actions ._eli3_af_btn:hover {
  background: rgba(255,255,255,0.25);
}

._eli3_af_section {
  margin-bottom: 16px;
}
._eli3_af_section_header {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  padding: 8px 4px;
  border-bottom: 1px solid #cbd5e1;
  margin-bottom: 8px;
}
._eli3_af_empty {
  padding: 24px 12px;
  text-align: center;
  color: #94a3b8;
  font-size: 12px;
}

._eli3_af_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 12px 14px;
  margin-bottom: 8px;
}
._eli3_af_card[data-uid] ._eli3_af_card_header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 4px;
}
._eli3_af_card_name {
  font: 700 14px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_af_card_badges {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}
._eli3_af_badge {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  border-radius: 2px;
}
._eli3_af_badge_role {
  background: #e0e7ff; color: #3730a3; border: 1px solid #c7d2fe;
}
._eli3_af_badge_active {
  background: #dcfce7; color: #14532d; border: 1px solid #86efac;
}
._eli3_af_badge_trial {
  background: #fef3c7; color: #92400e; border: 1px solid #fde68a;
}
._eli3_af_badge_offboarded {
  background: #f1f5f9; color: #64748b; border: 1px solid #cbd5e1;
}
._eli3_af_badge_legacy {
  background: #fde68a; color: #78350f; border: 1px solid #fbbf24;
}

._eli3_af_card_meta {
  font: 500 10.5px/1.4 'Inter', sans-serif;
  color: #64748b;
  margin-bottom: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}
._eli3_af_card_meta span { white-space: nowrap; }

._eli3_af_card_actions {
  display: flex;
  gap: 6px;
  margin: 6px 0;
  flex-wrap: wrap;
}

._eli3_af_btn {
  font: 600 11px/1 'Inter', sans-serif;
  padding: 6px 10px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-bottom-width: 2px;
  color: #0f172a;
  cursor: pointer;
  border-radius: 3px;
  transition: filter 0.12s;
}
._eli3_af_btn:hover { filter: brightness(0.97); }
._eli3_af_btn_primary {
  background: linear-gradient(180deg, #1565c0 0%, #0d47a1 100%);
  border-color: #0d47a1;
  color: #fff;
}
._eli3_af_btn_primary:hover { filter: brightness(1.08); }

._eli3_af_btn_mini {
  font: 600 10px/1 'Inter', sans-serif;
  padding: 3px 6px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 2px;
  transition: filter 0.12s;
}
._eli3_af_btn_mini:hover { filter: brightness(0.95); }
._eli3_af_btn_danger {
  background: linear-gradient(180deg, #fef2f2 0%, #fee2e2 100%);
  border-color: #fca5a5;
  color: #991b1b;
}

._eli3_af_settings,
._eli3_af_tools,
._eli3_af_overrides {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
  font-size: 11px;
}
._eli3_af_settings_header,
._eli3_af_tools_header,
._eli3_af_overrides_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  margin-bottom: 4px;
}
._eli3_af_settings_list,
._eli3_af_tools_list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px 12px;
}
._eli3_af_settings_row,
._eli3_af_tools_row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  color: #475569;
  padding: 1px 0;
}
._eli3_af_settings_key { font-weight: 700; color: #0f172a; }
._eli3_af_settings_val { color: #1565c0; }
._eli3_af_tools_id { flex: 1; color: #0f172a; }
._eli3_af_tools_disabled { color: #b91c1c; font-weight: 700; font-size: 9px; }
._eli3_af_tools_actions { display: flex; gap: 2px; }

._eli3_af_overrides_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef3c7;
  border: 1px solid #fde68a;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #92400e;
}

/* Installed-tools line — at-a-glance list of tool IDs in card meta */
._eli3_af_installed_line {
  margin: 4px 0 4px 0;
  padding: 6px 8px;
  background: #f8fafc;
  border-left: 3px solid #1565c0;
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #475569;
  word-break: break-all;
}
._eli3_af_installed_line_legacy {
  border-left-color: #fbbf24;
}
._eli3_af_installed_label {
  font: 700 9.5px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #0f172a;
  margin-right: 4px;
}

/* Excluded-tools section — tools where user is in audienceEmailExcludes */
._eli3_af_excluded {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
}
._eli3_af_excluded_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #b91c1c;
  margin-bottom: 4px;
}
._eli3_af_excluded_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #991b1b;
}
._eli3_af_excluded_id { flex: 1; font-weight: 600; }

._eli3_af_form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eli3_af_form_row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 10px;
  align-items: center;
}
._eli3_af_form_row label {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
._eli3_af_form_row input,
._eli3_af_form_row select,
._eli3_af_form_row textarea {
  font: 500 12px/1.3 'Inter', sans-serif;
  padding: 6px 8px;
  border: 1px solid #cbd5e1;
  border-radius: 2px;
  background: #fff;
  color: #0f172a;
  outline: none;
  width: 100%;
  box-sizing: border-box;
}
._eli3_af_form_row input:focus,
._eli3_af_form_row select:focus,
._eli3_af_form_row textarea:focus {
  border-color: #1565c0;
}
._eli3_af_form_val_static {
  font: 500 11.5px/1.3 'Inter', sans-serif;
  color: #475569;
  padding: 4px 0;
}
._eli3_af_req { color: #b91c1c; }
._eli3_af_radio {
  display: inline-block;
  padding: 2px 0;
  font-size: 11px;
}

._eli3_af_error {
  background: #fff;
  border: 1px solid #fca5a5;
  border-left: 4px solid #b91c1c;
  padding: 16px;
  border-radius: 0;
}
._eli3_af_error h2 {
  margin: 0 0 8px 0;
  font: 700 16px/1.2 'Georgia', serif;
  color: #991b1b;
}
._eli3_af_error p {
  margin: 6px 0;
  font-size: 12px;
  color: #475569;
}
._eli3_af_error code {
  background: #f1f5f9;
  padding: 1px 6px;
  border-radius: 2px;
  font-family: 'Monaco', monospace;
  font-size: 11px;
}
